create extension if not exists pgcrypto;
create table if not exists companies(id uuid primary key default gen_random_uuid(),name text not null,document text default '',phone text default '',email text default '',logo_url text default '',active boolean default true,created_at timestamptz default now());
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,company_id uuid references companies(id) on delete cascade,role text not null default 'company',name text default '',active boolean default true,created_at timestamptz default now());
create table if not exists company_settings(company_id uuid primary key references companies(id) on delete cascade,prefix text default 'ORC',validity_days int default 7,payment text default '',deadline text default '',warranty text default '',terms text default '',followup_days int default 3,quote_counter int default 0,receipt_counter int default 0);
create table if not exists clients(id text primary key,company_id uuid references companies(id) on delete cascade,name text not null,whatsapp text default '',phone text default '',email text default '',document text default '',address text default '',district text default '',zip text default '',city text default '',state text default '',notes text default '',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists catalog_items(id text primary key,company_id uuid references companies(id) on delete cascade,name text not null,description text default '',category text default '',type text default 'servico',unit text default 'un',price_cents int default 0,cost_cents int default 0,active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists quotes(id text primary key,company_id uuid references companies(id) on delete cascade,client_id text references clients(id) on delete set null,number text not null,status text default 'draft',subtotal_cents int default 0,discount_cents int default 0,additional_cents int default 0,freight_cents int default 0,total_cents int default 0,payment text default '',validity_days int default 7,validity_date timestamptz,deadline text default '',warranty text default '',notes text default '',show_pix boolean default true,sent_at timestamptz,viewed_at timestamptz,approved_at timestamptz,rejected_at timestamptz,signed_at timestamptz,rejection_reason text default '',signer_name text default '',signature_file_id uuid,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists quote_items(id text primary key,quote_id text references quotes(id) on delete cascade,position int default 0,name_snapshot text not null,description_snapshot text default '',unit_snapshot text default 'un',quantity numeric default 1,unit_price_cents int default 0,total_cents int default 0);
create table if not exists receipts(id text primary key,company_id uuid references companies(id) on delete cascade,client_id text,quote_id text,number text,value_cents int default 0,ref text default '',extenso text default '',notes text default '',created_at timestamptz default now());
create table if not exists digital_cards(company_id uuid primary key references companies(id) on delete cascade,profession text default '',description text default '',city text default '',instagram text default '',facebook text default '');
create table if not exists quote_public_links(id uuid primary key default gen_random_uuid(),quote_id text references quotes(id) on delete cascade,token_hash text unique not null,expires_at timestamptz not null,revoked_at timestamptz,last_accessed_at timestamptz,created_at timestamptz default now());
create table if not exists quote_events(id uuid primary key default gen_random_uuid(),quote_id text references quotes(id) on delete cascade,event_type text not null,actor_type text not null,actor_user_id uuid,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id) on delete cascade,quote_id text references quotes(id) on delete cascade,type text not null,title text not null,message text not null,read_at timestamptz,created_at timestamptz default now());
create table if not exists file_assets(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id) on delete cascade,quote_id text,bucket text,path text,kind text,created_at timestamptz default now());
